const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const siberia = ee.Geometry.Rectangle([80, 50, 120, 55]); // Southern Siberia region

  const date1 = '2018-10-14';
  const date2 = '2018-10-29';

  // 2. Data Acquisition - MODIS Snow Cover
  const modisSnow = ee.ImageCollection('MODIS/006/MOD10A1')
    .filterBounds(siberia);

  const img1 = modisSnow.filterDate(date1, ee.Date(date1).advance(1, 'day')).first();
  const img2 = modisSnow.filterDate(date2, ee.Date(date2).advance(1, 'day')).first();

  // Check if images exist
  const img1Exists = img1 ? true : false;
  const img2Exists = img2 ? true : false;

  if (!img1Exists || !img2Exists) {
    console.log(`Images found - Oct 14: ${img1Exists}, Oct 29: ${img2Exists}`);
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Extract snow cover data (NDSI_Snow_Cover band, values 0-100)
  const snowBand = 'NDSI_Snow_Cover';

  // Mask out fill values (values > 100 are clouds/invalid)
  const maskSnow = function(image) {
    const snow = image.select(snowBand);
    return snow.updateMask(snow.lte(100));
  };

  const snow1 = maskSnow(img1);
  const snow2 = maskSnow(img2);

  // Calculate statistics
  const stats1 = snow1.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: siberia,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2 = snow2.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: siberia,
    scale: 1000,
    maxPixels: 1e9
  });

  const mean1 = stats1.get('NDSI_Snow_Cover_mean');
  const count1 = stats1.get('NDSI_Snow_Cover_count');
  const mean2 = stats2.get('NDSI_Snow_Cover_mean');
  const count2 = stats2.get('NDSI_Snow_Cover_count');

  // Get actual values
  const mean1Val = mean1.getInfo();
  const count1Val = count1.getInfo();
  const mean2Val = mean2.getInfo();
  const count2Val = count2.getInfo();

  console.log(`Oct 14 Snow: ${mean1Val ? mean1Val.toFixed(1) : 'N/A'}% (Pixels: ${count1Val})`);
  console.log(`Oct 29 Snow: ${mean2Val ? mean2Val.toFixed(1) : 'N/A'}% (Pixels: ${count2Val})`);

  // Check for no valid pixels
  if (count1Val === 0 || count2Val === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failure
  if (mean1Val === null || mean2Val === null || 
      isNaN(mean1Val) || isNaN(mean2Val) ||
      mean1Val < 0 || mean1Val > 100 || mean2Val < 0 || mean2Val > 100) {
    console.log("<answer>C3</answer>");
    return;
  }

  // 4. Final Answer - Check if snow cover increased
  if (mean2Val > mean1Val) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
